import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.CNDaxUod.js";const g=JSON.parse('{"title":"Web app","description":"","frontmatter":{},"headers":[],"relativePath":"guide/web-app.md","filePath":"guide/web-app.md"}'),r={name:"guide/web-app.md"};function o(i,e,d,h,l,p){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="web-app" tabindex="-1">Web app <a class="header-anchor" href="#web-app" aria-label="Permalink to &quot;Web app&quot;">​</a></h1><p>AsyncUp&#39;s console lives at <strong><code>https://HOST/app</code></strong>. It is a single-page app served by the same process as the Chat bot and the JSON API, so there is nothing extra to deploy.</p><h2 id="signing-in" tabindex="-1">Signing in <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Signing in&quot;">​</a></h2><p>The sign-in page offers whichever methods are configured:</p><table tabindex="0"><thead><tr><th>Method</th><th>Who lands where</th></tr></thead><tbody><tr><td><strong>Continue with Google</strong></td><td>Workspace admins get the console; everyone else gets their own page</td></tr><tr><td><strong>Continue with SSO</strong> (SAML)</td><td>Same split, with the admin role taken from the IdP group attribute</td></tr><tr><td><strong>Operator token</strong> (<code>OPERATOR_TOKEN</code>)</td><td>The console, acting as the workspace operator. Kept in the browser tab only; switch it off under <em>Settings › Sign-in &amp; SSO</em> once a real method works</td></tr></tbody></table><p>Setting these up: <a href="./enterprise-sso.html">Sign-in</a>.</p><p>On a fresh install an admin lands in the <strong>guided setup</strong> (<code>/app/setup</code>): Cloud project → service account → Chat app configuration with a live check for the first signed event → optional sign-in → the first standup from a template, run immediately. Progress is saved as you go; the welcome page detects a working Chat connection and skips straight to the standup step. <a href="./first-standup.html">Guided setup and first test</a> walks through it.</p><h2 id="what-s-there" tabindex="-1">What&#39;s there <a class="header-anchor" href="#what-s-there" aria-label="Permalink to &quot;What&#39;s there&quot;">​</a></h2><ul><li><strong>Standups</strong> — stats strip (submitted today, participation, open blockers, missing), the table, and per standup: <strong>Overview</strong> (today&#39;s run polled live, recent runs, open blockers, schedule), <strong>History</strong> (every run with full answers, CSV export), <strong>Insights</strong> (participation by person, mood and blocker charts) and <strong>Settings</strong> (schedule with time pickers, questions, mood, the People grid and roster group, escalation, webhook with a signed test, digest, and a Danger zone to archive, unarchive or delete).</li><li><strong>Blockers</strong> — every open, acknowledged or resolved blocker across the standups you can see, with filters and the same actions as in Chat.</li><li><strong>Reports</strong> — participation, team mood and blockers over 4, 8 or 12 weeks, for all standups or one.</li><li><strong>Team</strong> — everyone on a roster with role, standups, timezone and status; roster changes with confirmation.</li><li><strong>Settings</strong> — General, Google Chat (with live verification), Sign-in &amp; SSO, MCP server, API &amp; tokens, Danger zone (disconnect Chat; delete all history — both behind a typed confirmation).</li><li><strong>My standups</strong> (<code>/app/me</code>) — for everyone else: today&#39;s standup with an <em>Answer in Chat</em> link and <em>Skip today</em> (which asks for a one-line reason), recent answers, timezone, vacation mode and <em>My schedule</em>.</li></ul><p>Admins see the whole workspace. <strong>Managers</strong> — people who administer at least one standup — see and manage their own standups, blockers, reports and team without Workspace-admin rights. Everyone else gets the personal page.</p><h2 id="people" tabindex="-1">People <a class="header-anchor" href="#people" aria-label="Permalink to &quot;People&quot;">​</a></h2><p>A standup&#39;s <strong>Settings → People</strong> grid lists everyone in its Chat space, or everyone in the Google Group it follows (<a href="./directory.html">Directory and group rosters</a>). Per person:</p><table tabindex="0"><thead><tr><th>Column</th><th>Meaning</th></tr></thead><tbody><tr><td>On standup</td><td>Prompted for this standup</td></tr><tr><td>Required</td><td>Listed as missing when they don&#39;t answer. The others still get the prompt but never count as missing</td></tr><tr><td>Mon–Sun</td><td>The days they work. Unticked days mean no prompt, and never missing. The standup&#39;s own off days are greyed out</td></tr></tbody></table><p><strong>Roster</strong> switches between <em>Picked from the space</em> and <em>Everyone in a Google Group</em>. With a group, <strong>Sync now</strong> and the last sync time appear, and people you untick stay off. The create form uses the same grid, with everyone in the space ticked to start.</p><p>Personal weeks, days off and time-off approvals also live under <strong>Team → Edit schedule</strong>, <strong>My page → My schedule</strong> and <strong>Team → Requests</strong> — see <a href="./schedules.html">Personal schedules</a>.</p><h2 id="naming-archiving-and-deleting" tabindex="-1">Naming, archiving and deleting <a class="header-anchor" href="#naming-archiving-and-deleting" aria-label="Permalink to &quot;Naming, archiving and deleting&quot;">​</a></h2><ul><li>Standup names are unique across the workspace, archived standups included, ignoring case. The create form flags a clash before you press Create.</li><li><strong>Archive</strong> (Danger zone, type <code>ARCHIVE</code>) stops prompts and keeps history. <strong>Unarchive</strong> resumes on the next scheduled day.</li><li><strong>Delete</strong> removes an archived standup with every run, answer, blocker and poll, after you type its name. Only workspace admins can delete. Messages already in Chat stay, and people&#39;s own weeks and days off are kept.</li></ul><h2 id="security-notes" tabindex="-1">Security notes <a class="header-anchor" href="#security-notes" aria-label="Permalink to &quot;Security notes&quot;">​</a></h2><ul><li>Browser sessions are signed cookies (<code>SECRET_KEY</code>); state-changing API calls from the app carry an <code>X-Requested-With</code> header as CSRF proof.</li><li>The operator token is only ever sent as a bearer header and is never stored server-side beyond the environment variable.</li><li>Secrets (service-account key, OAuth secret, SAML certificate) are encrypted at rest and never echoed back by the API — the app only ever learns that they are set.</li><li>The API and the app share one authorisation model; see the <a href="./api.html">API guide</a> for the exact rules per endpoint.</li></ul>',19)])])}const u=t(r,[["render",o]]);export{g as __pageData,u as default};
